async def act(page):
    """
    From the current New Product form state, fill the required fields for the new simple product:
      - Name: Energy-Bulk Man Yoga Pant
      - Price: 69.99
      - Qty: 50
      - Stock Availability: In Stock
      - Size: 38
      - Color: Yellow

    The Save click is the final action (it may navigate away). Uses select_option for comboboxes.
    """
    # Wait until page is idle
    await page.wait_for_load_state("networkidle")

    # --- Knowledge base functions reasoning ---
    # There are no helper functions provided in the knowledge_base for this task, so none are used.

    # 1) Ensure General tab is active so we can fill the Name and attributes like Size/Color
    try:
        general_link = page.get_by_role("link", name="General")
        if await general_link.count() > 0:
            await general_link.click()
            await page.wait_for_load_state("networkidle")
            await page.wait_for_timeout(300)
    except Exception:
        # ignore if already active or not present
        pass

    # 2) Fill Name. Use explicit table->rowgroup->row path if present, fallback to textbox search
    filled_name = False
    try:
        # Try an explicit row that commonly holds the Name field
        name_row = page.get_by_role("table").get_by_role("rowgroup").get_by_role(
            "row", name=lambda n: n and "name" in n.lower()
        )
        if await name_row.count() > 0:
            name_tb = name_row.get_by_role("textbox", name=lambda n: n and "name" in n.lower())
            if await name_tb.count() > 0:
                await name_tb.fill("Energy-Bulk Man Yoga Pant")
                filled_name = True
    except Exception:
        pass

    if not filled_name:
        # fallback: any textbox whose accessible name includes 'name'
        try:
            tb = page.get_by_role("textbox", name=lambda n: n and "name" in n.lower())
            if await tb.count() > 0:
                await tb.fill("Energy-Bulk Man Yoga Pant")
                filled_name = True
        except Exception:
            pass

    # 3) Click Prices to make sure Price field is visible, then set Price
    try:
        prices_link = page.get_by_role("link", name="Prices")
        if await prices_link.count() > 0:
            await prices_link.click()
            await page.wait_for_load_state("networkidle")
            await page.wait_for_timeout(300)
    except Exception:
        pass

    # The accessibility tree includes an exact row for Price; prefer that explicit path if present
    try:
        price_row = page.get_by_role("table").get_by_role("rowgroup").get_by_role(
            "row", name="Price * [USD] [GLOBAL]"
        )
        if await price_row.count() > 0:
            price_tb = price_row.get_by_role("textbox", name="Price *")
            if await price_tb.count() > 0:
                await price_tb.fill("69.99")
            else:
                # fallback to any textbox with 'price' in its name
                any_price = page.get_by_role("textbox", name=lambda n: n and "price" in n.lower())
                if await any_price.count() > 0:
                    await any_price.fill("69.99")
    except Exception:
        # fallback: any textbox with 'price' in its accessible name
        try:
            any_price = page.get_by_role("textbox", name=lambda n: n and "price" in n.lower())
            if await any_price.count() > 0:
                await any_price.fill("69.99")
        except Exception:
            pass

    # 4) Click Inventory to expose Qty and Stock Availability controls
    try:
        inv_link = page.get_by_role("link", name="Inventory")
        if await inv_link.count() > 0:
            await inv_link.click()
            await page.wait_for_load_state("networkidle")
            await page.wait_for_timeout(300)
    except Exception:
        # fallback to tab role
        try:
            inv_tab = page.get_by_role("tab", name=lambda n: n and "inventory" in n.lower())
            if await inv_tab.count() > 0:
                await inv_tab.click()
                await page.wait_for_timeout(300)
        except Exception:
            pass

    # 5) Set Quantity = 50
    try:
        qty_tb = page.get_by_role("textbox", name=lambda n: n and ("qty" in n.lower() or "quantity" in n.lower()))
        if await qty_tb.count() > 0:
            await qty_tb.fill("50")
    except Exception:
        pass

    # 6) Set Stock Availability -> In Stock (combobox/select)
    try:
        stock_cb = page.get_by_role("combobox", name=lambda n: n and ("stock" in n.lower() or "availability" in n.lower()))
        if await stock_cb.count() > 0:
            await stock_cb.select_option("In Stock")
    except Exception:
        pass

    # 7) Set Size -> 38 (combobox anywhere on the form)
    try:
        size_cb = page.get_by_role("combobox", name=lambda n: n and "size" in n.lower())
        if await size_cb.count() > 0:
            await size_cb.select_option("38")
    except Exception:
        pass

    # 8) Set Color -> Yellow (combobox anywhere on the form). Try common case variants.
    try:
        color_cb = page.get_by_role("combobox", name=lambda n: n and "color" in n.lower())
        if await color_cb.count() > 0:
            for opt in ["Yellow", "yellow"]:
                try:
                    await color_cb.select_option(opt)
                    break
                except Exception:
                    continue
    except Exception:
        pass

    # 9) Final action: click Save (scope under document). This will navigate away so it must be last.
    try:
        doc = page.get_by_role("document")
        if await doc.count() > 0:
            save_btn = doc.get_by_role("button", name="Save")
            if await save_btn.count() > 0:
                await save_btn.click()
                return
    except Exception:
        pass

    # fallback: any Save button on the page
    try:
        save_any = page.get_by_role("button", name="Save")
        if await save_any.count() > 0:
            await save_any.click()
            return
    except Exception:
